<script lang="ts">import { page } from '$app/state'; import { getLearnerGradebook } from '$lib/services/gradebook-data'; import { authState } from '$lib/auth.svelte'; import { navigate } from '$lib/utils/navigation'; let data = $state<{entries: any[]; average: number; pending: number} | null>(null); const courseId = $derived(page.params.courseId as string); $effect(() => { if (!authState.loading) { if (!authState.user) navigate('/auth/login'); else load() } }); async function load() { data = (await getLearnerGradebook({ courseId })).data }</script>
<main class="container mx-auto max-w-3xl p-6"><h1 class="text-2xl font-semibold">Grades</h1>{#if data}<p class="my-4">Current average: {data.average.toFixed(1)}% · Pending/unreleased: {data.pending}</p>{#each data.entries as entry}<div class="flex justify-between border-b py-2"><span>{entry.title} · {entry.category}</span><span>{entry.status === 'graded' && entry.released ? `${entry.pointsEarned}/${entry.pointsPossible}` : entry.released ? 'Pending' : 'Unreleased'}</span></div>{/each}{:else}<p>Loading grades…</p>{/if}</main>
